for _dk, _dv in _DOMAIN_RAW.items():
    _h, _e1, _e2, _w, _r, _rw, _q, _t, _s = _split(_dv)
    DOMAIN_BANKS[_dk] = {
        "hook": _h,
        "example": _e1,
        "example2": _e2,
        "misconception": {"wrong": _w, "right": _r},
        "real_world": _rw,
        "question": _q,
        "transition": _t,
        "summary": _s,
    }

_SUBJECT_DOMAIN: tuple[tuple[str, str], ...] = (
    ("physics", "physics"),
    ("biology", "biology"),
    ("science", "biology"),
    ("chemistry", "chemistry"),
    ("math", "math"),
    ("mathematics", "math"),
    ("geography", "geography"),
    ("history", "history"),
    ("english", "english"),
    ("environment", "environment"),
    ("environmental", "environment"),
    ("evs", "environment"),
    ("civics", "civics"),
    ("political", "civics"),
    ("economics", "economics"),
    ("computer", "computer"),
    ("cs", "computer"),
    ("ict", "computer"),
    ("health", "health"),
)

_EMPTY = {
    "hook": "",
    "example": "",
    "example2": "",
    "misconception": {},
    "real_world": "",
    "question": "",
    "transition": "",
    "summary": "",
    "covered": False,
}


def _from_pack(key: str) -> dict[str, Any]:
    h, e1, e2, w, r, rw, q, t, s = _PACK[key]
    return {
        "hook": h,
        "example": e1,
        "example2": e2,
        "misconception": {"wrong": w, "right": r},
        "real_world": rw,
        "question": q,
        "transition": t,
        "summary": s,
        "covered": True,
    }


def _from_domain(d: dict[str, Any]) -> dict[str, Any]:
    return {
        "hook": d.get("hook", ""),
        "example": d.get("example", ""),
        "example2": d.get("example2", ""),
        "misconception": dict(d.get("misconception") or {}),
        "real_world": d.get("real_world", ""),
        "question": d.get("question", ""),
        "transition": d.get("transition", ""),
        "summary": d.get("summary", ""),
        "covered": True,
    }


def lookup_banks(topic: str, subject: str = "", claim: str = "") -> dict[str, Any]:
    """Return dict with keys hook, example, example2, misconception, real_world,
    question, transition, summary, covered (bool).

    Match exact topic (case-insensitive), else keyword/domain match from
    claim+topic+subject, else empty with covered=False.
    """
    key = (topic or "").strip().lower()
    if key in _PACK:
        return _from_pack(key)

    blob = f"{topic} {subject} {claim}".lower()
    for dom_key in sorted(DOMAIN_BANKS.keys(), key=len, reverse=True):
        if dom_key in blob:
            return _from_domain(DOMAIN_BANKS[dom_key])

    subj = (subject or "").strip().lower()
    for needle, dom in _SUBJECT_DOMAIN:
        if needle in subj or needle in blob:
            if dom in DOMAIN_BANKS:
                return _from_domain(DOMAIN_BANKS[dom])

    return dict(_EMPTY)


def coverage_ratio(topics: list[str]) -> float:
    """Fraction of topics with an exact HOOK_BANK entry (case-insensitive)."""
    if not topics:
        return 0.0
    hits = sum(1 for t in topics if (t or "").strip().lower() in HOOK_BANK)
    return hits / len(topics)
